import {
    Table,
    TranslatedTextColumn,
    ReferenceColumn,
    DomainIdColumn,
    DateTimeColumn,
    SlushBucketColumn,
    BooleanColumn,
    ChoiceColumn,
    GuidColumn,
    TemplateValueColumn,
    GenericColumn,
    TableNameColumn,
    StringColumn,
    IntegerColumn,
    ListColumn,
    DomainPathColumn,
} from '@servicenow/sdk/core'

export const kb_knowledge_base = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    display: 'title',
    label: 'Knowledge Base',
    name: 'kb_knowledge_base',
    schema: {
        description: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Description',
            maxLength: 4000,
        }),
        owner: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Owner',
            mandatory: true,
            referenceTable: 'sys_user',
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the record belongs',
                    label: 'Domain',
                    plural: 'Domains',
                    language: 'en',
                },
            ],
        }),
        application: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            cascadeRule: 'none',
            default:
                'javascript:(function() {if (gs.isCurrentApplicationInGlobalScope()) return gs.getCurrentApplicationScope(); else return gs.getCurrentApplicationId();})()',
            label: [
                {
                    hint: 'Application scope for this knowledge base',
                    label: 'Application',
                    plural: 'Applications',
                    language: 'en',
                },
            ],
            mandatory: true,
            referenceTable: 'sys_scope',
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        workflow: ReferenceColumn({
            active: false,
            attributes: {
                encode_utf8: false,
            },
            label: 'Publish workflow',
            referenceTable: 'wf_workflow',
            referenceQual: "javascript:'sys_idIN'+(new KBWorkflow().getWorkflowIds().join());",
        }),
        mandatory_fields: SlushBucketColumn({
            script: 'getKBMandatoryFields()',
            label: 'Mandatory fields',
            maxLength: 1000,
        }),
        disable_suggesting: BooleanColumn({
            default: false,
            label: [
                {
                    hint: "Removes 'Flag Article' button from the article view for all articles belonging to this knowledge base",
                    label: 'Disable suggesting',
                    plural: 'Disable suggesting',
                    language: 'en',
                },
            ],
        }),
        approval_description: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: [
                {
                    hint: 'A short description of who will approve content in this knowledge base',
                    label: 'Approval description',
                    plural: 'Approval descriptions',
                    language: 'en',
                },
            ],
            maxLength: 4000,
        }),
        kb_version: ChoiceColumn({
            default: '3',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Knowledge release version',
                    label: 'Release version',
                    plural: 'Release versions',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        disable_mark_as_helpful: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Removes mark as helpful option for all articles belonging to this knowledge base',
                    label: 'Disable mark as helpful',
                    plural: 'Disable mark as helpfuls',
                    language: 'en',
                },
            ],
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        template: TemplateValueColumn({
            dependent: 'table',
            label: 'Set default knowledge field values',
        }),
        card_color: GenericColumn({
            columnType: 'color',
            label: [
                {
                    hint: 'Color that represents this Knowledge Base',
                    label: 'Card color',
                    plural: 'Card colors',
                    language: 'en',
                },
            ],
        }),
        question_annotation: GenericColumn({
            attributes: {
                encode_utf8: false,
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            columnType: 'translated_html',
            label: [
                {
                    hint: 'Annotation to question',
                    label: 'Question annotation',
                    plural: 'Question annotations',
                    language: 'en',
                },
            ],
            maxLength: 65000,
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
        checklist: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Checklist',
            referenceTable: 'kb_quality_checklist',
        }),
        table: TableNameColumn({
            attributes: {
                base_start: true,
            },
            default: 'kb_knowledge',
            label: 'Table',
            readOnly: true,
            tableReference: true,
        }),
        icon: GenericColumn({
            attributes: {
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: [
                {
                    hint: 'Icon that represents this Knowledge Base',
                    label: 'Icon',
                    plural: 'Icons',
                    language: 'en',
                },
            ],
        }),
        enable_socialqa: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Enable social questions and answers for the knowledge base',
                    label: 'Enable social questions and answers',
                    plural: 'Enable social questions and answers',
                    language: 'en',
                },
            ],
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        title: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: [
                {
                    hint: 'The title of the knowledge base. This must be unique.',
                    label: 'Title',
                    plural: 'Titles',
                    language: 'en',
                },
            ],
            mandatory: true,
            maxLength: 100,
            textIndex: true,
            unique: true,
        }),
        disable_category_editing: BooleanColumn({
            default: false,
            label: [
                {
                    label: 'Disable category editing',
                    plural: 'Disable category editing',
                    language: 'en',
                },
            ],
        }),
        order: IntegerColumn({
            label: [
                {
                    hint: 'Order of importance for pinned articles query',
                    label: 'Order',
                    plural: 'Orders',
                    language: 'en',
                },
            ],
        }),
        article_validity: IntegerColumn({
            label: [
                {
                    hint: 'Number of days the article is valid for.',
                    label: 'Article Validity',
                    plural: 'Article Validities',
                    language: 'en',
                },
            ],
            maxLength: 32,
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        kb_managers: ListColumn({
            attributes: {
                no_email: true,
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Managers',
            referenceTable: 'sys_user',
        }),
        disable_commenting: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Disables writing comments to an article for all articles belonging to this knowledge base',
                    label: 'Disable commenting',
                    plural: 'Disable commenting',
                    language: 'en',
                },
            ],
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
        retire_workflow: ReferenceColumn({
            active: false,
            attributes: {
                encode_utf8: false,
            },
            label: 'Retire workflow',
            referenceTable: 'wf_workflow',
            referenceQual: "javascript:'sys_idIN'+(new KBWorkflow().getWorkflowIds().join());",
        }),
        data_policy: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Data policy',
            referenceTable: 'sys_data_policy2',
        }),
        disable_rating: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Removes star rating option for all articles belonging to this knowledge base',
                    label: 'Disable rating',
                    plural: 'Disable ratings',
                    language: 'en',
                },
            ],
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        kb_retire_flow: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Retire flow',
            referenceTable: 'sys_hub_flow',
            referenceQual: 'javascript: new KBFlow().getKnowledgeFlows()',
        }),
        kb_publish_flow: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Publish flow',
            referenceTable: 'sys_hub_flow',
            referenceQual: 'javascript: new KBFlow().getKnowledgeFlows()',
        }),
    },
})
